//! Sorting networks for `sortN`: Bert Dobbelaere optimal networks for `2 <= N <= 64`
//! (mechanically transcribed from `ref/cranexpr`'s `optimal.rs`) and iterative-friendly
//! Batcher odd-even mergesort for `65 <= N <= 1024`.

const std = @import("std");

pub const max_sort_n: usize = 1024;

pub const Pair = struct {
    a: u16,
    b: u16,
};

const OptimalPair = struct {
    a: u8,
    b: u8,
};

const NetworkSlice = struct {
    offset: u16,
    count: u16,
};

/// Appends the comparator pairs `(a, b)` with `a < b` for a sorting network of `n` elements.
/// Returns `error.SortTooLarge` if `n > max_sort_n`.
pub fn appendNetwork(allocator: std.mem.Allocator, out: *std.ArrayList(Pair), n: usize) (std.mem.Allocator.Error || error{SortTooLarge})!void {
    if (n > max_sort_n) return error.SortTooLarge;
    if (n < 2) return;

    if (n <= 64) {
        const entry = network_index[n - 2];
        const slice = optimal_comparators[entry.offset..][0..entry.count];
        try out.ensureUnusedCapacity(allocator, slice.len);
        for (slice) |p| {
            out.appendAssumeCapacity(.{ .a = p.a, .b = p.b });
        }
        return;
    }

    try appendBatcherOddEven(allocator, out, n);
}

fn appendBatcherOddEven(allocator: std.mem.Allocator, out: *std.ArrayList(Pair), n: usize) std.mem.Allocator.Error!void {
    const p = std.math.ceilPowerOfTwoAssert(usize, n);
    // Iterative Batcher odd-even mergesort (Knuth Algorithm M, zero recursion).
    var t: usize = 1;
    while (t < p) : (t *= 2) {
        var k: usize = t;
        while (k >= 1) : (k /= 2) {
            const start = k % t;
            var j = start;
            while (j <= p - 1 - k) : (j += 2 * k) {
                var i: usize = 0;
                while (i < @min(k, p - j - k)) : (i += 1) {
                    const lo = i + j;
                    const hi = i + j + k;
                    if (@divFloor(lo, t * 2) == @divFloor(hi, t * 2)) {
                        if (lo < n and hi < n) {
                            try out.append(allocator, .{ .a = @intCast(lo), .b = @intCast(hi) });
                        }
                    }
                }
            }
        }
    }
}

