test "optimal sorting networks satisfy 0-1 principle for N=2..14" {
    const allocator = std.testing.allocator;
    var pairs: std.ArrayList(Pair) = .empty;
    defer pairs.deinit(allocator);

    for (2..15) |n| {
        pairs.clearRetainingCapacity();
        try appendNetwork(allocator, &pairs, n);
        const total = @as(usize, 1) << @intCast(n);
        for (0..total) |mask| {
            var vals: [16]u8 = @splat(0);
            for (0..n) |i| {
                vals[i] = @intCast((mask >> @intCast(i)) & 1);
            }
            for (pairs.items) |p| {
                if (vals[p.a] > vals[p.b]) {
                    std.mem.swap(u8, &vals[p.a], &vals[p.b]);
                }
            }
            for (1..n) |i| {
                try std.testing.expect(vals[i - 1] <= vals[i]);
            }
        }
    }
}

test "Batcher odd-even network sorts N=65, 289, 1024 and rejects 1025" {
    const allocator = std.testing.allocator;
    var pairs: std.ArrayList(Pair) = .empty;
    defer pairs.deinit(allocator);

    try std.testing.expectError(error.SortTooLarge, appendNetwork(allocator, &pairs, 1025));

    const test_sizes = [_]usize{ 65, 100, 289, 1024 };
    var prng = std.Random.DefaultPrng.init(0x5A17_C0DE);
    const rand = prng.random();

    for (test_sizes) |n| {
        pairs.clearRetainingCapacity();
        try appendNetwork(allocator, &pairs, n);
        var vals: [max_sort_n]u32 = undefined;
        // Descending + random permutations
        for (0..n) |i| vals[i] = @intCast(n - 1 - i);
        for (pairs.items) |p| {
            if (vals[p.a] > vals[p.b]) std.mem.swap(u32, &vals[p.a], &vals[p.b]);
        }
        for (1..n) |i| try std.testing.expect(vals[i - 1] <= vals[i]);

        for (0..n) |i| vals[i] = rand.int(u32);
        for (pairs.items) |p| {
            if (vals[p.a] > vals[p.b]) std.mem.swap(u32, &vals[p.a], &vals[p.b]);
        }
        for (1..n) |i| try std.testing.expect(vals[i - 1] <= vals[i]);
    }
}
